CREATE OR REPLACE FUNCTION public.drain_interview_queue() RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN DELETE FROM public.interview_sessions WHERE expires_at<=now(); IF EXISTS(SELECT 1 FROM public.interview_engine_state WHERE id='interview' AND paused) OR NOT EXISTS(SELECT 1 FROM public.interview_sessions WHERE status IN ('queued','processing') AND expires_at>now()) THEN PERFORM cron.unschedule(jobid) FROM cron.job WHERE jobname='interview-queue-retry'; END IF; END $$;
REVOKE ALL ON FUNCTION public.drain_interview_queue() FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.drain_interview_queue() TO service_role;